import React from "react";
import {
  AbsoluteFill,
  Img,
  interpolate,
  random,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';


export type FrankensteinFloatingProps = Record<string, any>;

const FrankensteinFloating: React.FC<FrankensteinFloatingProps> = ({
  backgroundColor = "#121212",
  transparentBackground = true,
  durationInSeconds = 10,
  headImage = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/68b3bce086ab4f7fa345ead32b79882c.png",
  headCount = 30,
  wiggleAmount = 50,
  baseSpeed = 1,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safely handle transparent background without hex manipulation
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  const totalFrames = fps * durationInSeconds;
  const baseSize = Math.min(width, height) * 0.3; // 30% of the smallest screen dimension

  // Pre-calculate head properties using deterministic randomness
  const heads = Array.from({ length: headCount })
    .map((_, i) => {
      const rDuration = random(`duration-${i}`);
      const rDelay = random(`delay-${i}`);
      const rX = random(`x-${i}`);
      const rPhase = random(`phase-${i}`);
      const rScale = random(`scale-${i}`);
      const rRot = random(`rot-${i}`);
      const rSpin = random(`spin-${i}`);

      // 0.3 to 1.0 base scale
      const scale = 0.3 + rScale * 0.7;

      // Parallax logic: larger/closer heads move slightly faster
      const speedMultiplier = 0.5 + rScale * 1.0;
      
      // Base float time to cross the screen is ~8 seconds at speed 1
      const baseFloatDurationFrames = (fps * 8) / baseSpeed;
      
      // Actual float duration varied by ±20% for natural randomness
      const actualFloatDuration =
        (baseFloatDurationFrames / speedMultiplier) * (0.8 + rDuration * 0.4);

      // Distribute heads evenly across the timeline (including before frame 0 so it starts filled)
      const spawnWindow = totalFrames + actualFloatDuration;
      const startFrame = rDelay * spawnWindow - actualFloatDuration;

      const progress = interpolate(
        frame,
        [startFrame, startFrame + actualFloatDuration],
        [0, 1],
        {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        }
      );

      // Float from below the bottom edge to above the top edge
      const startY = height + baseSize;
      const endY = -baseSize;
      const yPos = interpolate(progress, [0, 1], [startY, endY]);

      // Wiggle on the X axis using a sine wave
      const wigglePhase = rPhase * Math.PI * 2;
      const wiggle =
        Math.sin((frame / fps) * 2 + wigglePhase) * wiggleAmount * scale;
      const baseX = rX * width;
      const xPos = baseX + wiggle;

      // Gentle rotation as they float
      const baseRotation = (rRot - 0.5) * 60;
      const spin = interpolate(
        progress,
        [0, 1],
        [baseRotation, baseRotation + (rSpin - 0.5) * 180]
      );

      // Smaller heads in the back are slightly more transparent for depth
      const opacity = 0.5 + rScale * 0.5;

      return { i, xPos, yPos, spin, scale, opacity, progress, rScale };
    })
    // Sort so smaller heads render behind larger heads (Z-index by array order)
    .sort((a, b) => a.rScale - b.rScale);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {heads.map(({ i, xPos, yPos, spin, scale, opacity, progress }) => {
        // Unmount heads that are completely offscreen to optimize rendering
        if (progress <= 0 || progress >= 1) {
          return null;
        }

        return (
          <Img
            key={i}
            src={headImage}
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              width: baseSize,
              height: baseSize,
              objectFit: "contain",
              // Offset by half baseSize to center the image on the coordinates
              transform: `translate(${xPos - baseSize / 2}px, ${
                yPos - baseSize / 2
              }px) scale(${scale}) rotate(${spin}deg)`,
              opacity,
              transition: "none",
            }}
          />
        );
      })}
    </AbsoluteFill>
  );
};

export default FrankensteinFloating;